use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{SystemTime, UNIX_EPOCH};
use tokio::sync::mpsc;
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct IndexEntry {
    pub doc_id: String,
    pub content: String,
    pub priority: u32,
    pub timestamp: u64,
    pub tenant_id: String,
}

#[derive(Clone, Debug)]
pub struct PendingOperation {
    pub entry: IndexEntry,
    pub op_type: OpType,
    pub sequence_num: u64,
}

#[derive(Clone, Debug, PartialEq)]
pub enum OpType {
    Insert,
    Update,
    Delete,
}

pub struct SearchIndexService {
    index: Arc<RwLock<HashMap<String, IndexEntry>>>,
    pending_queue: Arc<RwLock<Vec<PendingOperation>>>,
    sequence_counter: Arc<RwLock<u64>>,
    commit_threshold: usize,
}

impl SearchIndexService {
    pub fn new(commit_threshold: usize) -> Self {
        SearchIndexService {
            index: Arc::new(RwLock::new(HashMap::new())),
            pending_queue: Arc::new(RwLock::new(Vec::new())),
            sequence_counter: Arc::new(RwLock::new(0)),
            commit_threshold,
        }
    }

    /// Submit an indexing operation. Returns the assigned sequence number.
    pub async fn submit_operation(&self, entry: IndexEntry, op_type: OpType) -> Result<u64, String> {
        // Validate the request before accepting it into the pending queue.
        validate_index_request(&entry)?;

        let seq = {
            let mut counter = self.sequence_counter.write().unwrap();
            *counter += 1;
            *counter
        };

        let op = PendingOperation {
            entry,
            op_type,
            sequence_num: seq,
        };

        {
            let mut queue = self.pending_queue.write().unwrap();
            queue.push(op);
        }

        // Auto-commit when threshold reached
        if self.pending_queue.read().unwrap().len() >= self.commit_threshold {
            self.commit_batch().await;
        }

        Ok(seq)
    }

    /// Commit pending operations to the index.
    /// Operations are applied in strict sequence order to maintain causal consistency.
    pub async fn commit_batch(&self) {
        let mut ops = {
            let mut queue = self.pending_queue.write().unwrap();
            let ops = queue.clone();
            queue.clear();
            ops
        };

        // Sort by sequence number ascending to preserve causal ordering.
        // This ensures operations are applied in submission order regardless of priority.
        ops.sort_by(|a, b| a.sequence_num.cmp(&b.sequence_num));

        let mut index = self.index.write().unwrap();
        for op in ops {
            match op.op_type {
                OpType::Insert => {
                    index.insert(op.entry.doc_id.clone(), op.entry);
                }
                OpType::Update => {
                    index.insert(op.entry.doc_id.clone(), op.entry);
                }
                OpType::Delete => {
                    index.remove(&op.entry.doc_id);
                }
            }
        }
    }

    /// Query the current state of a document in the index
    pub fn query_document(&self, doc_id: &str) -> Option<IndexEntry> {
        let index = self.index.read().unwrap();
        index.get(doc_id).cloned()
    }

    /// Get pending operations visible only to the requesting tenant
    pub fn get_pending_ops(&self, tenant_id: &str) -> Vec<PendingOperation> {
        let queue = self.pending_queue.read().unwrap();
        queue.iter()
            .filter(|op| op.entry.tenant_id == tenant_id)
            .cloned()
            .collect()
    }

    /// Health check endpoint for k8s liveness probe
    pub fn health_check(&self) -> bool {
        let queue_len = self.pending_queue.read().unwrap().len();
        let index_accessible = self.index.read().is_ok();
        queue_len < 10000 && index_accessible
    }
}

/// Kubernetes admission webhook validator for index operations
pub fn validate_index_request(entry: &IndexEntry) -> Result<(), String> {
    if entry.doc_id.is_empty() {
        return Err("doc_id cannot be empty".to_string());
    }
    if entry.content.len() > 1_000_000 {
        return Err("content exceeds maximum size".to_string());
    }
    if entry.priority > 1000 {
        return Err("priority exceeds maximum allowed value".to_string());
    }
    if entry.tenant_id.is_empty() {
        return Err("tenant_id is required".to_string());
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_causal_ordering_preserved() {
        let service = SearchIndexService::new(10);

        // Tenant A submits a delete for doc "shared-123"
        let entry_a = IndexEntry {
            doc_id: "shared-123".to_string(),
            content: "".to_string(),
            priority: 100,
            tenant_id: "tenant-a".to_string(),
            timestamp: 1000,
        };
        service.submit_operation(entry_a, OpType::Delete).await.unwrap();

        // Tenant B submits a higher-priority update after the delete
        let entry_b = IndexEntry {
            doc_id: "shared-123".to_string(),
            content: "legitimate update".to_string(),
            priority: 999,
            tenant_id: "tenant-b".to_string(),
            timestamp: 2000,
        };
        service.submit_operation(entry_b.clone(), OpType::Update).await.unwrap();

        service.commit_batch().await;

        // Sequence ordering is preserved: delete (seq=1) then update (seq=2)
        // Result: doc exists with tenant B's content, as expected
        let result = service.query_document("shared-123");
        assert!(result.is_some());
        assert_eq!(result.unwrap().content, "legitimate update");
    }
}
